  const w2 = Math.cos(x*0.025-t*0.4)*10 + Math.sin(y*0.02+t*0.28)*14;
  const w3 = Math.sin((x+y)*0.01+t*0.15)*8;
  const sx = x + w1 + w3, sy = y + w2 + w3;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.5],
